"""matplotlib.hatch — hatch pattern definitions."""


_hatch_types = {
    '/': 'diagonal',
    '\\': 'back_diagonal',
    '|': 'vertical',
    '-': 'horizontal',
    '+': 'cross',
    'x': 'diagonal_cross',
    'o': 'small_circle',
    'O': 'large_circle',
    '.': 'dots',
    '*': 'stars',
}


def get_path(hatchpattern, density=6):
    """Return a :class:`matplotlib.path.Path` containing the hatch's
    geometry — concatenation of every pattern character's vertices.
    Mirrors upstream's ``hatch.get_path`` which renderers use to draw
    the pattern across a patch's interior."""
    from matplotlib.path import Path
    import numpy as _np
    if not hatchpattern:
        return Path([(0, 0)])
    patterns = _hatch_pattern_factory(hatchpattern, density)
    total = sum(p.num_vertices for p in patterns)
    if total == 0:
        return Path([(0, 0)])
    vertices = _np.zeros((total, 2))
    codes = _np.zeros(total, dtype=_np.uint8)
    offset = 0
    for p in patterns:
        n = p.num_vertices
        if n == 0: continue
        sub_v = _np.zeros((n, 2))
        sub_c = _np.zeros(n, dtype=_np.uint8)
        p.set_vertices_and_codes(sub_v, sub_c)
        vertices[offset:offset + n] = sub_v
        codes[offset:offset + n] = sub_c
        offset += n
    return Path(vertices, codes)


def _hatch_pattern_factory(hatchpattern, density):
    """Build the list of hatch-pattern objects for ``hatchpattern`` — one
    per distinct character class. The renderer tiles each across the
    patch interior."""
    out = []
    if '-' in hatchpattern or '+' in hatchpattern:
        out.append(HorizontalHatch(hatchpattern, density))
    if '|' in hatchpattern or '+' in hatchpattern:
        out.append(VerticalHatch(hatchpattern, density))
    if '/' in hatchpattern or 'x' in hatchpattern:
        out.append(NorthEastHatch(hatchpattern, density))
    if '\\' in hatchpattern or 'x' in hatchpattern:
        out.append(SouthEastHatch(hatchpattern, density))
    if 'o' in hatchpattern:
        out.append(SmallCircles(hatchpattern, density))
    if 'O' in hatchpattern:
        out.append(LargeCircles(hatchpattern, density))
    if '.' in hatchpattern:
        out.append(SmallFilledCircles(hatchpattern, density))
    if '*' in hatchpattern:
        out.append(Stars(hatchpattern, density))
    return out


import numpy as _np


# ─── Added: missing public Hatch classes from upstream hatch.py ───
#
# Each hatch pattern produces a list of vertices and path-codes which a
# real backend would tile across the patch interior. Plotly draws hatches
# natively from a single-character pattern string, so these classes are
# kept as lightweight metadata holders — they implement the upstream
# ``set_vertices_and_codes(vertices, codes)`` contract so any code path
# that walks them won't crash.


class HatchPatternBase:
    """Base class for hatch patterns. Subclasses override
    :meth:`set_vertices_and_codes` to populate the two output arrays
    with the geometry that tiles the hatch.
    """

    def __init__(self, hatch, density):
        self.hatch = hatch
        self.density = density
        self.num_lines = 0
        self.num_vertices = 0

    def set_vertices_and_codes(self, vertices, codes):
        # No-op base implementation. Subclasses override this and
        # mutate ``vertices``/``codes`` in place starting at offset 0.
        pass


class HorizontalHatch(HatchPatternBase):
    """Horizontal lines, drawn for each ``-`` or ``+`` character in
    ``hatch``. The unit cell is a 1×1 square; we draw ``count`` lines
    at evenly spaced y-positions.
    """

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        # `+` is "cross" — counts toward both horizontal and vertical.
        self.num_lines = density * (hatch.count('-') + hatch.count('+'))
        # 2 endpoints per line.
        self.num_vertices = self.num_lines * 2

    def set_vertices_and_codes(self, vertices, codes):
        steps = _np.linspace(0, 1, self.num_lines + 1)[:-1] if self.num_lines else []
        for i, y in enumerate(steps):
            vertices[i * 2]     = (0.0, y)
            vertices[i * 2 + 1] = (1.0, y)
            codes[i * 2]     = 1   # MOVETO
            codes[i * 2 + 1] = 2   # LINETO


class VerticalHatch(HatchPatternBase):
    """Vertical lines, drawn for each ``|`` or ``+`` character in
    ``hatch``."""

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_lines = density * (hatch.count('|') + hatch.count('+'))
        self.num_vertices = self.num_lines * 2

    def set_vertices_and_codes(self, vertices, codes):
        steps = _np.linspace(0, 1, self.num_lines + 1)[:-1] if self.num_lines else []
        for i, x in enumerate(steps):
            vertices[i * 2]     = (x, 0.0)
            vertices[i * 2 + 1] = (x, 1.0)
            codes[i * 2]     = 1
            codes[i * 2 + 1] = 2


class NorthEastHatch(HatchPatternBase):
    """Lines running from lower-left to upper-right (``/``)."""

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_lines = density * (hatch.count('/') + hatch.count('x'))
        self.num_vertices = self.num_lines * 2

    def set_vertices_and_codes(self, vertices, codes):
        # We span the unit cell diagonally; shifts spread lines across.
        if self.num_lines == 0:
            return
        shifts = _np.linspace(-1, 1, self.num_lines + 1)[:-1]
        for i, s in enumerate(shifts):
            vertices[i * 2]     = (s, 0.0)
            vertices[i * 2 + 1] = (s + 1.0, 1.0)
            codes[i * 2]     = 1
            codes[i * 2 + 1] = 2


class SouthEastHatch(HatchPatternBase):
    """Lines running from upper-left to lower-right (``\\``)."""

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_lines = density * (hatch.count('\\') + hatch.count('x'))
        self.num_vertices = self.num_lines * 2

    def set_vertices_and_codes(self, vertices, codes):
        if self.num_lines == 0:
            return
        shifts = _np.linspace(-1, 1, self.num_lines + 1)[:-1]
        for i, s in enumerate(shifts):
            vertices[i * 2]     = (s, 1.0)
            vertices[i * 2 + 1] = (s + 1.0, 0.0)
            codes[i * 2]     = 1
            codes[i * 2 + 1] = 2


class Shapes(HatchPatternBase):
    """Generic shape-tile hatch. Subclasses set ``filled`` and override
    :meth:`shape_vertices` to return the local-frame outline of one
    shape; this base class tiles that shape across the unit cell.
    """

    filled = False
    size = 1.0

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = 0
        self.num_vertices = 0

    def shape_vertices(self):
        # Default: a tiny unit-circle approximation as 8-gon.
        n = 8
        angles = _np.linspace(0, 2 * _np.pi, n, endpoint=False)
        return _np.column_stack([_np.cos(angles), _np.sin(angles)]) * self.size

    def set_vertices_and_codes(self, vertices, codes):
        shape = self.shape_vertices()
        per = len(shape)
        # Tile copies of the shape on a regular grid.
        side = int(_np.ceil(_np.sqrt(self.num_shapes))) or 1
        positions = []
        for r in range(side):
            for c in range(side):
                positions.append(((c + 0.5) / side, (r + 0.5) / side))
                if len(positions) >= self.num_shapes:
                    break
            if len(positions) >= self.num_shapes:
                break
        out_v, out_c = [], []
        for (px, py) in positions:
            for j, (sx, sy) in enumerate(shape):
                out_v.append((px + sx, py + sy))
                out_c.append(1 if j == 0 else 2)
        # Mutate caller-supplied arrays in place where possible.
        for i, ((vx, vy), cd) in enumerate(zip(out_v, out_c)):
            if i >= len(vertices):
                break
            vertices[i] = (vx, vy)
            codes[i] = cd


class Circles(Shapes):
    """Circles tiled across the unit cell — base for the small/large
    variants below."""

    filled = False
    size = 0.1

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = density * (hatch.count('o') + hatch.count('O'))
        self.num_vertices = self.num_shapes * 8


class SmallCircles(Circles):
    size = 0.05

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = density * hatch.count('o')
        self.num_vertices = self.num_shapes * 8


class LargeCircles(Circles):
    size = 0.15

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = density * hatch.count('O')
        self.num_vertices = self.num_shapes * 8


class SmallFilledCircles(SmallCircles):
    filled = True
    size = 0.04

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = density * hatch.count('.')
        self.num_vertices = self.num_shapes * 8


class Stars(Shapes):
    """Five-pointed stars tiled across the unit cell."""
    filled = True
    size = 0.07

    def __init__(self, hatch, density):
        super().__init__(hatch, density)
        self.num_shapes = density * hatch.count('*')
        # 10 vertices per star (alternating outer/inner points).
        self.num_vertices = self.num_shapes * 10

    def shape_vertices(self):
        outer = []
        for k in range(10):
            angle = _np.pi / 2 + k * _np.pi / 5
            r = self.size if k % 2 == 0 else self.size * 0.5
            outer.append((r * _np.cos(angle), r * _np.sin(angle)))
        return _np.asarray(outer)


# Registry mirrors upstream's ``_hatch_types`` mapping but to classes
# rather than to the character names.
_hatch_pattern_classes = (
    HorizontalHatch, VerticalHatch, NorthEastHatch, SouthEastHatch,
    SmallCircles, LargeCircles, SmallFilledCircles, Stars,
)
